def prioritise_risks(risks):
    rows = []
    for r in risks:
        for key in ('likelihood', 'impact'):
            v = r[key]
            if not isinstance(v, int) or isinstance(v, bool) or not 1 <= v <= 5:
                raise ValueError(f'{key} must be an integer from 1 to 5')
        score = r['likelihood'] * r['impact']
        level = 'LOW' if score <= 5 else 'MEDIUM' if score <= 12 else 'HIGH' if score <= 19 else 'CRITICAL'
        rows.append((r['name'], score, level))
    return sorted(rows, key=lambda x: (-x[1], x[0]))

def residual_risk(score, control_effects):
    residual = float(score)
    for e in control_effects:
        if not 0 <= e <= 1:
            raise ValueError('control effects must be between 0 and 1')
        residual *= 1 - e
    return round(residual, 2)

def validate_input(text, max_chars, max_lines):
    if not text.strip():
        return (False, 'EMPTY')
    if len(text) > max_chars:
        return (False, 'TOO_LONG')
    if text.count('\n') + 1 > max_lines:
        return (False, 'TOO_MANY_LINES')
    if any(ord(c) < 32 and c not in '\n\t' for c in text):
        return (False, 'CONTROL_CHARS')
    return (True, 'OK')

def truncate_tokens(text, max_tokens):
    if max_tokens < 1:
        raise ValueError('max_tokens must be at least 1')
    words = text.split()
    return (' '.join(words[:max_tokens]), len(words) > max_tokens)

