def mask_cards(text):
    count = 0

    def repl(m):
        nonlocal count
        digits = m.group(0).replace(' ', '').replace('-', '')
        if luhn_valid(digits):
            count += 1
            return '**** **** **** ' + digits[-4:]
        return m.group(0)

    masked = re.sub(r'\b(?:\d[ -]?){12,18}\d\b', repl, text)
    return (masked, count)

def moderate(scores, thresholds):
    flagged = sorted(c for c, s in scores.items() if c in thresholds and s >= thresholds[c])
    return {'flagged': flagged, 'action': 'BLOCK' if flagged else 'ALLOW'}

def threshold_counts(examples, threshold):
    out = {'caught': 0, 'missed': 0, 'false_alarms': 0, 'passed': 0}
    for score, harmful in examples:
        flagged = score >= threshold
        if harmful:
            out['caught' if flagged else 'missed'] += 1
        else:
            out['false_alarms' if flagged else 'passed'] += 1
    return out


def best_threshold(examples, candidates, max_missed):
    for t in sorted(candidates, reverse=True):
        if threshold_counts(examples, t)['missed'] <= max_missed:
            return t
    return None

def confusion(y_true, y_pred):
    if len(y_true) != len(y_pred):
        raise ValueError('lists must have the same length')
    out = {'tp': 0, 'fp': 0, 'fn': 0, 'tn': 0}
    for t, p in zip(y_true, y_pred):
        if t and p:
            out['tp'] += 1
        elif p:
            out['fp'] += 1
        elif t:
            out['fn'] += 1
        else:
            out['tn'] += 1
    return out

def prf(tp, fp, fn):
    p = tp / (tp + fp) if tp + fp else 0.0
    r = tp / (tp + fn) if tp + fn else 0.0
    f1 = 2 * p * r / (p + r) if p + r else 0.0
    return {'precision': round(p, 4), 'recall': round(r, 4), 'f1': round(f1, 4)}

