def _words(text):
    return {w for w in re.findall(r'[a-z0-9]+', text.lower()) if len(w) > 3}


def groundedness(answer_sentences, sources):
    if not answer_sentences:
        return (1.0, [])
    source_words = [_words(s) for s in sources]
    unsupported = []
    for sentence in answer_sentences:
        w = _words(sentence)
        if w and not any(len(w & sw) * 2 >= len(w) for sw in source_words):
            unsupported.append(sentence)
    supported = len(answer_sentences) - len(unsupported)
    return (round(supported / len(answer_sentences), 4), unsupported)

import re


def unsupported_numbers(answer, sources):
    pattern = r'\d+(?:\.\d+)?'
    known = set()
    for s in sources:
        known |= set(re.findall(pattern, s))
    return sorted(set(re.findall(pattern, answer)) - known)

