def check_tool_call(call, registry):
    spec = registry.get(call['tool'])
    if spec is None:
        return ['unknown_tool']
    args = call.get('args', {})
    errors = [f'missing:{a}' for a in spec['required'] if a not in args]
    for name, value in args.items():
        if name not in spec['args']:
            errors.append(f'unexpected:{name}')
        elif not _type_ok(value, spec['args'][name]):
            errors.append(f'type:{name}')
    return sorted(errors)

import posixpath


def safe_join(base, user_path):
    if posixpath.isabs(user_path):
        raise ValueError('absolute paths are not allowed')
    joined = posixpath.normpath(posixpath.join(base, user_path))
    if joined != base and not joined.startswith(base + '/'):
        raise ValueError('path escapes the base folder')
    return joined

def needs_approval(action, policy):
    if action['tool'] in policy['always']:
        return (True, 'ALWAYS')
    if action.get('amount', 0) > policy['amount_limit']:
        return (True, 'AMOUNT')
    return (False, 'AUTO')

def run_plan(steps, allowed_tools, approved):
    executed = []
    for step in steps:
        if step['tool'] not in allowed_tools:
            return {'executed': executed, 'status': 'BLOCKED', 'stopped_at': step['id']}
        if step['tool'].startswith('danger_') and step['id'] not in approved:
            return {'executed': executed, 'status': 'WAITING_APPROVAL', 'stopped_at': step['id']}
        executed.append(step['id'])
    return {'executed': executed, 'status': 'DONE', 'stopped_at': None}

class SlidingWindowLimiter:
    def __init__(self, limit, window_seconds):
        self.limit = limit
        self.window = window_seconds
        self.history = {}

    def allow(self, user, t):
        times = [x for x in self.history.get(user, []) if x > t - self.window]
        if len(times) >= self.limit:
            self.history[user] = times
            return False
        times.append(t)
        self.history[user] = times
        return True

def abuse_flags(events, max_blocked=3, max_per_minute=30):
    blocked, per_minute = {}, {}
    for e in events:
        if e['blocked']:
            blocked[e['user']] = blocked.get(e['user'], 0) + 1
        key = (e['user'], e['minute'])
        per_minute[key] = per_minute.get(key, 0) + 1
    flags = {}
    for user, n in blocked.items():
        if n > max_blocked:
            flags.setdefault(user, []).append('REPEATED_ATTACKS')
    for (user, _), n in per_minute.items():
        if n > max_per_minute and 'FLOODING' not in flags.get(user, []):
            flags.setdefault(user, []).append('FLOODING')
    return {u: sorted(f) for u, f in flags.items()}

def attack_success_rate(results):
    attempts, wins = {}, {}
    for cat, ok in results:
        attempts[cat] = attempts.get(cat, 0) + 1
        wins[cat] = wins.get(cat, 0) + (1 if ok else 0)
    return {c: round(wins[c] / attempts[c], 3) for c in sorted(attempts)}

def weakest_categories(results, min_attempts, top):
    attempts, wins = {}, {}
    for cat, ok in results:
        attempts[cat] = attempts.get(cat, 0) + 1
        wins[cat] = wins.get(cat, 0) + (1 if ok else 0)
    eligible = [c for c in attempts if attempts[c] >= min_attempts]
    eligible.sort(key=lambda c: (-wins[c] / attempts[c], c))
    return eligible[:top]

