def find_banned(text, banned):
    t = unicodedata.normalize('NFKC', text).lower()
    t = ''.join(LEET.get(c, c) for c in t if c not in ZERO_WIDTH)
    collapsed = re.sub(r'[^a-z]', '', t)
    return sorted(w for w in banned if w in collapsed)

def demographic_parity(preds, groups):
    pos, tot = {}, {}
    for p, g in zip(preds, groups):
        tot[g] = tot.get(g, 0) + 1
        pos[g] = pos.get(g, 0) + (1 if p else 0)
    if not tot:
        return {'rates': {}, 'gap': 0.0}
    rates = {g: pos[g] / tot[g] for g in sorted(tot)}
    return {'rates': {g: round(r, 3) for g, r in rates.items()}, 'gap': round(max(rates.values()) - min(rates.values()), 3)}

def equal_opportunity(y_true, y_pred, groups):
    hits, pos = {}, {}
    for t, p, g in zip(y_true, y_pred, groups):
        if t:
            pos[g] = pos.get(g, 0) + 1
            hits[g] = hits.get(g, 0) + (1 if p else 0)
    rates = {g: hits[g] / pos[g] for g in sorted(pos)}
    gap = max(rates.values()) - min(rates.values()) if len(rates) >= 2 else 0.0
    return {'tpr': {g: round(r, 3) for g, r in rates.items()}, 'gap': round(gap, 3)}

def ece(confidences, correct, bins=5):
    if not confidences:
        return 0.0
    groups = {}
    for c, ok in zip(confidences, correct):
        groups.setdefault(min(int(c * bins), bins - 1), []).append((c, ok))
    n = len(confidences)
    total = 0.0
    for items in groups.values():
        acc = sum(1 for _, ok in items if ok) / len(items)
        avg = sum(c for c, _ in items) / len(items)
        total += len(items) / n * abs(acc - avg)
    return round(total, 4)

def reliability_table(confidences, correct, bins=5):
    groups = {}
    for c, ok in zip(confidences, correct):
        groups.setdefault(min(int(c * bins), bins - 1), []).append((c, ok))
    table = []
    for b in sorted(groups):
        items = groups[b]
        avg = sum(c for c, _ in items) / len(items)
        acc = sum(1 for _, ok in items if ok) / len(items)
        table.append((round(b / bins, 2), round((b + 1) / bins, 2), len(items), round(avg, 3), round(acc, 3)))
    return table

def selective(confidences, correct, threshold):
    if not confidences:
        return {'coverage': 0.0, 'accuracy': 0.0}
    answered = [ok for c, ok in zip(confidences, correct) if c >= threshold]
    acc = sum(answered) / len(answered) if answered else 0.0
    return {'coverage': round(len(answered) / len(confidences), 3), 'accuracy': round(acc, 3)}

def threshold_for(confidences, correct, target):
    for t in sorted(set(confidences)):
        answered = [ok for c, ok in zip(confidences, correct) if c >= t]
        if answered and sum(answered) / len(answered) >= target:
            return t
    return None

def run_suite(cases, guard):
    failures = [c['id'] for c in cases if guard(c['input']) != c['expect']]
    rate = (len(cases) - len(failures)) / len(cases) if cases else 0.0
    return {'pass_rate': round(rate, 3), 'failures': failures}

def regression_gate(baseline, current, max_drop):
    bad = sorted(m for m, v in baseline.items() if m not in current or current[m] < v - max_drop)
    return (not bad, bad)

