def watermark_z(tokens, key, gamma=0.5):
    T = len(tokens) - 1
    if T < 1:
        return 0.0
    G = sum(int(hashlib.md5(f'{key}|{tokens[i - 1]}|{tokens[i]}'.encode()).hexdigest(), 16) % 2 == 0 for i in range(1, len(tokens)))
    return round((G - gamma * T) / math.sqrt(T * gamma * (1 - gamma)), 3)

