import math


def fit_ratings(items, comparisons, lr=0.1, epochs=100):
    r = {i: 0.0 for i in items}
    for _ in range(epochs):
        for w, l in comparisons:
            p = 1 / (1 + math.exp(r[l] - r[w]))
            r[w] += lr * (1 - p)
            r[l] -= lr * (1 - p)
    return {i: round(r[i], 3) + 0.0 for i in items}

