INJECTION = [r'ignore (all |the )?(previous|prior|above) instructions', r'system prompt', r'developer mode']
LEET = {'0': 'o', '1': 'i', '3': 'e', '4': 'a', '5': 's', '@': 'a', '$': 's'}


def luhn_valid(digits):
    if not digits.isdigit() or not 13 <= len(digits) <= 19:
        return False
    total = 0
    for i, ch in enumerate(reversed(digits)):
        d = int(ch)
        if i % 2 == 1:
            d = d * 2 - 9 if d * 2 > 9 else d * 2
        total += d
    return total % 10 == 0


def guardrail(text, max_chars, banned):
    reasons = []
    if not text.strip():
        reasons.append('EMPTY')
    if len(text) > max_chars:
        reasons.append('TOO_LONG')
    if any(re.search(p, text, re.IGNORECASE) for p in INJECTION):
        reasons.append('INJECTION')
    collapsed = re.sub(r'[^a-z]', '', ''.join(LEET.get(c, c) for c in text.lower()))
    if any(w in collapsed for w in banned):
        reasons.append('BANNED')
    for m in re.finditer(r'\b(?:\d[ -]?){12,18}\d\b', text):
        if luhn_valid(m.group(0).replace(' ', '').replace('-', '')):
            reasons.append('CARD')
            break
    if any(r != 'CARD' for r in reasons):
        decision = 'BLOCK'
    elif reasons:
        decision = 'REDACT'
    else:
        decision = 'ALLOW'
    return {'decision': decision, 'reasons': reasons}

def safety_scorecard(metrics, targets):
    results = {}
    for name, (op, target) in targets.items():
        if name not in metrics:
            results[name] = 'MISSING'
            continue
        value = metrics[name]
        ok = value >= target if op == '>=' else value <= target
        results[name] = 'PASS' if ok else 'FAIL'
    passed = sum(1 for v in results.values() if v == 'PASS')
    total = len(targets)
    share = passed / total if total else 0.0
    grade = 'A' if total and passed == total else 'B' if share >= 0.8 else 'C' if share >= 0.5 else 'D'
    return {'results': results, 'passed': passed, 'total': total, 'grade': grade}
